const tabId = 725789930;

async function ddgSearch(query) {
  const url = `https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });
  return await browserjs(tabId, () => {
    const results = Array.from(document.querySelectorAll(".result__body")).map(el => {
      const a = el.querySelector(".result__snippet");
      const titleEl = el.querySelector(".result__title a");
      return {
        title: titleEl?.textContent?.trim(),
        url: titleEl?.href,
        snippet: a?.textContent?.trim()
      };
    });
    return results.slice(0, 5);
  });
}

