// Take a screenshot of the document in CryptPad
const ss = await browser.screenshot({ tabId });
console.log("CryptPad screenshot URI:", ss.image);

// Also let's check the document title in the top toolbar
// In earlier snapshot, title was: generic "Rich text - Fri, September 18, 2026" [ref=e18] focusable [tabindex]
// and generic "Click to edit" [ref=e21] clickable [cursor:pointer]
// Let's click the title to change it to "Deconstructing Trump's Venezuela Strategy (2017-2021)"
try {
  const snapshot = await browser.snapshot({ tabId });
  // Find ref for click to edit or title
  const editMatch = snapshot.text.match(/generic "Click to edit" \[ref=(\w+)\]/);
  if (editMatch) {
    const editRef = editMatch[1];
    await tool.element_interact({ tabId, ref: editRef, operation: "click" });
    await tool.keyboard_insert_text({ tabId, text: "Trump Venezuela Strategy Research Briefing Memo" });
    await tool.press({ tabId, keys: "Enter" });
    console.log("Renamed document title.");
  }
} catch (e) {
  console.log("Title edit note:", e.message);
}

